   -- The VRAM, with the power-on screen in the first 16 KB.
   type ram_t is array (0 to 2 ** ABITS - 1) of std_logic_vector(0 to 7);

   function init_ram return ram_t is
      variable r : ram_t := (others => (others => '0'));
   begin
      for i in INIT16K'range loop
         r(i) := INIT16K(i);
      end loop;
      return r;
   end function;

   signal ram : ram_t := init_ram;

begin
   -- Inferred read_first ram.
   process (clk)
   begin
      if rising_edge(clk) then
         dout <= ram(to_integer(unsigned(addr)));
         dout2 <= ram(to_integer(unsigned(addr2)));
         if we = '1' then
            ram(to_integer(unsigned(addr))) <= din;
         end if;
      end if;
   end process;

end rtl;
